  "results": [
    {
      "row_index": 549,
      "opening_text": "はじめまして。\nWebディレクターの大場李奈と申します。\n\n貴社サイトを拝見し、2001年の設立以来、仙台を拠点に飲食店から美容室、建設会社、大学のスポーツ団体まで、実に幅広い業種のWebサイト・グラフィック制作を手がけていらっしゃることに感銘を受けました。これだけ多様な業種のご案件を並行して進めておられると、案件ごとに求められる進行管理の勘所も異なり、制作リソースの調整にお時間を取られているのではないかと感じ、ご連絡いたしました。"
    },
    {
      "row_index": 555,
      "opening_text": "はじめまして。\nWebディレクターの大場李奈と申します。\n\n新潟県十日町市でお一人でMore⁺Designを運営され、「二人三脚」の丁寧なサポートを強みに掲げていらっしゃることを拝見しました。企画からデザイン、コーディング、保守運用までをご自身お一人で担われている分、複数の案件が同時に重なるタイミングでは進行管理に手が回りきらなくなる瞬間もあるのではないかと感じ、ご連絡いたしました。"
    },
    {
      "row_index": 558,
      "opening_text": "はじめまして。\nWebディレクターの大場李奈と申します。\n\n札幌を拠点に、単なる制作にとどまらずKPI設計や戦略立案まで踏み込んだWeb解析ベースのサイト制作に取り組んでいらっしゃることを拝見しました。分析や戦略提案に力を注がれる分、複数の制作案件が重なった際には進行管理そのものに割ける時間が限られてくるのではないかと感じ、ご連絡いたしました。"
    },
    {
      "row_index": 561,
      "opening_text": "はじめまして。\nWebディレクターの大場李奈と申します。\n\n苫小牧を拠点に、ホームページ制作から楽天市場のショップカスタマイズ、ロゴや名刺のグラフィックデザインまで幅広く手がけていらっしゃることを拝見しました。制作の窓口を一手に担われている分、ジャンルの異なるご依頼が重なるタイミングでは、ディレクション業務に十分な時間を割きにくくなる場面もあるのではないかと感じ、ご連絡いたしました。"
    },
    {
      "row_index": 563,
      "opening_text": "はじめまして。\nWebディレクターの大場李奈と申します。\n\n香川を拠点に、ホームページ制作にとどまらず写真撮影・動画撮影編集から多言語対応まで、ワンストップで幅広いご要望に応えていらっしゃることを拝見しました。対応領域が広い分、案件が重なるタイミングでは進行管理や各制作パートとの連携調整にお時間を取られているのではないかと感じ、ご連絡いたしました。"
    },
    {
      "row_index": 591,
      "opening_text": "はじめまして。\nWebディレクターの大場李奈と申します。\n\n川崎市を拠点に、2003年の設立以来、畳店やフレンチレストラン、産業機器メーカー、造園会社まで、業種を問わず幅広いお客様のホームページ制作とクラウド運用・営業戦略のご支援をされていらっしゃることを拝見しました。制作だけでなく経営面のご相談まで一手に引き受けていらっしゃる分、複数の案件が重なった際には進行管理に十分な時間を割きにくくなる場面もあるのではないかと感じ、ご連絡いたしました。"
    },
    {
      "row_index": 603,
      "opening_text": "はじめまして。\nWebディレクターの大場李奈と申します。\n\n神戸を拠点に、2007年の設立以来、チラシデザインからホームページ制作まで低価格で幅広く手がけられ、登録デザイナーの皆様とネットワークを組んで制作を進めていらっしゃることを拝見しました。案件ごとに異なる登録デザイナーの方々へ要件を橋渡しされる分、指示の整理や認識合わせに想像以上の手間がかかっているのではないかと感じ、ご連絡いたしました。"
    },
    {
      "row_index": 625,
      "opening_text": "はじめまして。\nWebディレクターの大場李奈と申します。\n\n東京・東池袋を拠点に、プロダクトデザインからパッケージ、そしてオリジナルブランドのフライリール「Graffiti」の企画・販売まで手がけていらっしゃることを拝見しました。商品企画から販売まで一貫してプロデュースされている分、Webサイトの制作・更新については専任で腰を据えて取り組む時間を確保しづらいのではないかと感じ、ご連絡いたしました。"
    },
    {
      "row_index": 626,
      "opening_text": "はじめまして。\nWebディレクターの大場李奈と申します。\n\n京都・伏見を拠点に、ロゴやパッケージ、看板といったグラフィックからホームページ制作、動画編集まで幅広い領域を手がけていらっしゃることを拝見しました。事業領域が広い分、Web案件が他の制作と重なるタイミングでは、ディレクションに割ける時間が限られてくるのではないかと感じ、ご連絡いたしました。"
    },
    {
      "row_index": 638,
      "opening_text": "はじめまして。\nWebディレクターの大場李奈と申します。\n\n群馬県前橋市を拠点に、Web制作に加えて撮影部門「スピカ写真室」を独立させるなど、企画から撮影、グラフィック、ECサイト構築、原稿執筆まで一気通貫で手がけていらっしゃることを拝見しました。眼科や内科クリニックをはじめ多業種のご依頼を抱えていらっしゃる分、複数の案件が重なった際には進行管理に十分な時間を割きにくくなる場面もあるのではないかと感じ、ご連絡いたしました。"
    },
    {
      "row_index": 640,
      "opening_text": "はじめまして。\nWebディレクターの大場李奈と申します。\n\n山梨を拠点に、2005年から個人でWebデザイナーとして活動され、デザイン会社からの外注案件を数多く手がけていらっしゃることを拝見しました。複数の制作会社から並行して案件を引き受けていらっしゃる分、それぞれの要件整理や進行管理にお一人で対応するのは負担が大きい時期もあるのではないかと感じ、ご連絡いたしました。"
    },
    {
      "row_index": 646,
      "opening_text": "はじめまして。\nWebディレクターの大場李奈と申します。\n\n大阪・守口を拠点に、「かくたまさこのファブリックステンシル グレープヴァイン」様のサイトのように、企画提案からデザイン、コーディング、CMS構築、更新作業まで一貫して手がけていらっしゃることを拝見しました。制作の入口から更新運用までをすべて自社で担われている分、案件が重なった際にはディレクション業務に十分な時間を割きにくくなる場面もあるのではないかと感じ、ご連絡いたしました。"
    },
    {
      "row_index": 668,
      "opening_text": "はじめまして。\nWebディレクターの大場李奈と申します。\n\n横浜を拠点に、デジタルマーケティング会社で200ページ以上のサイトディレクションを手がけられたご経験を活かし、女性向けホームページ制作からオンラインWEBスクールの運営まで幅広く手がけていらっしゃることを拝見しました。制作案件とスクール運営を並行して担われている分、複数の案件が重なるタイミングではディレクション業務に十分な時間を割きにくくなる場面もあるのではないかと感じ、ご連絡いたしました。"
    },
    {
      "row_index": 671,
      "opening_text": "はじめまして。\nWebディレクターの大場李奈と申します。\n\n長崎県佐世保市でご夫婦お二人でリムデザインを運営される傍ら、2023年からはスコーン専門店「mir」のECサイト運営もご自身で手がけていらっしゃることを拝見しました。ホームページ制作と自社ショップの運営を両立されている分、お客様の案件が重なるタイミングではディレクションに十分な時間を割きにくくなる場面もあるのではないかと感じ、ご連絡いたしました。"
    },
    {
      "row_index": 700,
      "opening_text": "はじめまして。\nWebディレクターの大場李奈と申します。\n\n神戸・姫路を拠点に、飲食店からファッションブランド、ホテルまで幅広い業種のホームページ制作に加え、ロゴやカスタムフォント制作まで手がけていらっしゃることを拝見しました。案件ごとに求められるデザインの幅が広い分、複数のご依頼が重なるタイミングでは進行管理に十分な時間を割きにくくなる場面もあるのではないかと感じ、ご連絡いたしました。"
    },
    {
      "row_index": 720,
      "opening_text": "はじめまして。\nWebディレクターの大場李奈と申します。\n\nさいたま市浦和区を拠点に、ホームページ制作やブログカスタマイズだけでなく、チラシやポスターといったDTP、さらにはキャラクターデザインまで幅広く手がけていらっしゃることを拝見しました。対応領域が広い分、複数の案件が重なるタイミングではWeb制作のディレクションに十分な時間を割きにくくなる場面もあるのではないかと感じ、ご連絡いたしました。"
    },
    {
      "row_index": 724,
      "opening_text": "はじめまして。\nWebディレクターの大場李奈と申します。\n\n京都府宇治市でお一人でSally WebDesignを運営され、これから開業される個人事業主の方に向けてホームページからLINEリッチメニュー、lit.link、名刺、動画制作まで幅広いサービスを手がけていらっしゃることを拝見しました。サービス領域が広くお一人で担われている分、複数のご依頼が重なるタイミングでは進行管理に手が回りきらなくなる場面もあるのではないかと感じ、ご連絡いたしました。"
    },
    {
      "row_index": 725,
      "opening_text": "はじめまして。\nWebディレクターの大場李奈と申します。\n\n福岡・北九州を拠点にホームページ制作を手がけられる一方、ご自身のブログでWebデザインの学習情報も発信されていらっしゃることを拝見しました。制作業務と情報発信を並行して担われている分、複数の案件が重なるタイミングでは進行管理に十分な時間を割きにくくなる場面もあるのではないかと感じ、ご連絡いたしました。"
    }
  ],
  "skip_not_production": [
    {
      "row_index": 624,
      "reason": "PHB Design株式会社は社名に「Design」を含むが、実態は薬局経営コンサルティング会社（在宅医療転換支援、服薬支援システムnondi、調剤DX支援シジダス等が主力事業）。Web制作は付随的な扱いに過ぎず、典型的なWeb/映像制作会社ではないため冒頭文の対象外とした。"
    }
  ],
  "failed": [
    {
      "row_index": 588,
      "reason": "http://www.nutscracker.net/ はSSL証明書エラー（証明書の有効期限切れ）でWebFetchが2回とも失敗。WebSearchで会社名・ドメインを複数パターンで検索したが、該当するWeb制作会社の情報を一切特定できず、サイトの実態確認ができなかった。"
    }
  ]
}

